export function PzIcon({ name, size = 22, className = "native-icon" }) {
  const src = ProjectZeroIcons[name];
  if (src) {
    return <img className={className} src={src} width={size} height={size} alt="" draggable={false} data-native-icon={name} style={{ width: size, height: size, flexShrink: 0, objectFit: "contain" }} />;
  }
  return <PzGlyph name={name} size={size} className={className} />;
}
